    deadlocks: body.summary?.deadlocks
  }
};

return [{ json: systemHealthData }];

// Database Performance Data Splitter
const inputData = $input.first().json;
const body = inputData.body ?? inputData;

const dbPerformanceData = {
  server: body.summary?.server ?? 'Unknown',
  timestamp: body.summary?.timestamp,
  database: body.database ?? {},
  locks: {
    waiting_sessions: body.locks?.waiting_sessions ?? 0,
    top_waiters: (body.locks?.top_waiters ?? []).slice(0, 5),
    blocking_chains: (body.locks?.blocking_chains ?? []).slice(0, 5)
  },
  vacuum: {
    top_dead_tuples: (body.vacuum?.top_dead_tuples ?? []).slice(0, 5)
  },
  bloat: {
    top_bloated_tables: (body.bloat?.top_bloated_tables ?? []).slice(0, 5),
    large_indexes: (body.bloat?.large_indexes ?? []).slice(0, 5)
  }
};

return [{ json: dbPerformanceData }];

// Backup & Recovery Data Splitter
const inputData = $input.first().json;
const body = inputData.body ?? inputData;

const backupRecoveryData = {
  server: body.summary?.server ?? 'Unknown',
  timestamp: body.summary?.timestamp,
  backup: body.backup ?? {},
  wal: body.wal ?? {},
  replication: body.replication ?? {},
  archive_mode: body.summary?.archive_mode
};

return [{ json: backupRecoveryData }];

// Security & Compliance Data Splitter
const inputData = $input.first().json;
const body = inputData.body ?? inputData;

const securityAlerts = (body.alerts ?? []).filter(alert => 
  alert.code?.includes('security') || 
  alert.code?.includes('auth') || 
  alert.code?.includes('privilege') ||
  alert.severity === 'critical'
);

const securityData = {
  server: body.summary?.server ?? 'Unknown',
  timestamp: body.summary?.timestamp,
  configuration: body.configuration ?? {},
  security_alerts: securityAlerts,
  all_alerts: body.alerts ?? []
};

return [{ json: securityData }];

// Storage & Capacity Data Splitter
const inputData = $input.first().json;
const body = inputData.body ?? inputData;

const storageData = {
  server: body.summary?.server ?? 'Unknown',
  timestamp: body.summary?.timestamp,
  storage_summary: body.storage_summary ?? {},
  disk_usage_percent: body.summary?.disk_usage_percent,
  storage: body.storage ?? {},
  largest_tables: (body.storage?.largest_tables ?? []).slice(0, 10),
  largest_indexes: (body.storage?.largest_indexes ?? []).slice(0, 10)
};

return [{ json: storageData }];

