// Consolidation Code - Aggregate all sub-agent outputs
const systemHealthIssues = $node['System Health Agent'].json?.issues ?? [];
const dbPerformanceIssues = $node['DB Performance Agent'].json?.issues ?? [];
const backupRecoveryIssues = $node['Backup Recovery Agent'].json?.issues ?? [];
const securityComplianceIssues = $node['Security Compliance Agent'].json?.issues ?? [];
const storageCapacityIssues = $node['Storage Capacity Agent'].json?.issues ?? [];

// Get server info from any input (they all have the same server info)
const serverInfo = $input.first().json;
const server = serverInfo.server ?? 'Unknown';
const timestamp = serverInfo.timestamp;

// Combine all issues
const allIssues = [
  ...systemHealthIssues.map(issue => ({ ...issue, category: 'System Health' })),
  ...dbPerformanceIssues.map(issue => ({ ...issue, category: 'Database Performance' })),
  ...backupRecoveryIssues.map(issue => ({ ...issue, category: 'Backup & Recovery' })),
  ...securityComplianceIssues.map(issue => ({ ...issue, category: 'Security & Compliance' })),
  ...storageCapacityIssues.map(issue => ({ ...issue, category: 'Storage & Capacity' }))
];

// Remove duplicates based on title
const uniqueIssues = allIssues.filter((issue, index, self) => 
  index === self.findIndex(i => i.title === issue.title)
);

// Sort by priority (Critical first, then High, Medium, Low)
const priorityOrder = { 'Critical': 1, 'High': 2, 'Medium': 3, 'Low': 4 };
const sortedIssues = uniqueIssues.sort((a, b) => 
  (priorityOrder[a.priority] || 5) - (priorityOrder[b.priority] || 5)
);

const consolidationData = {
  server,
  timestamp,
  total_issues: sortedIssues.length,
  issues_by_category: {
    'System Health': systemHealthIssues.length,
    'Database Performance': dbPerformanceIssues.length,
    'Backup & Recovery': backupRecoveryIssues.length,
    'Security & Compliance': securityComplianceIssues.length,
    'Storage & Capacity': storageCapacityIssues.length
  },
  issues: sortedIssues
};

return [{ json: consolidationData }];

const jiraTasks = [];
const inputItems = $input.all();

for (const item of inputItems) {
    if (item.json.output && Array.isArray(item.json.output)) {
        for (const issue of item.json.output) {
            const description = [
                `Description`,
                issue.Description || 'No description provided.',
                ``,
                `Immediate Remediation Steps`
            ].concat(issue['Immediate remediation steps'] || ['No immediate remediation steps provided.']).map(step => ` ${step}`)
            .concat([
                ``,
                `Preventative Actions and Proactive Monitoring Improvements`
            ])
            .concat(issue['Preventative actions and proactive monitoring improvements'] || ['No preventative actions provided.']).map(action => ` ${action}`)
            .join(String.fromCharCode(10));

            // Map priority: Critical=1, High=2, Medium=3
            const priStr = (issue.Priority || 'Medium').toLowerCase();
            const priorityMap = { critical: 1, high: 2, medium: 3 };
            const numericPriority = priorityMap[priStr] ?? 3;

            // Only create Jira tasks for priority 1 (Critical) and 2 (High)
            if (numericPriority <= 3) {
                const task = {
                    summary: issue.Issue || 'No summary provided.',
                    description: description,
                    priority: numericPriority,
                    labels: (issue.Issue || '').toLowerCase().split(' ').map(l => l.replace(/[^a-z0-9]/g, ''))
                };
                jiraTasks.push({ json: task });
            }
            // Else: skip Medium (3) and lower priorities
        }
    }
}

return jiraTasks;

const item = $input.first();
const inputData = item.json ?? item;

const envelope = inputData;

function bytesToHuman(bytes) {
  const value = Number(bytes);
  if (!Number.isFinite(value)) return null;
  const units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
  let unitIndex = 0;
  let n = value;
  while (n >= 1024 && unitIndex < units.length - 1) {
    n /= 1024;
    unitIndex += 1;
  }
  const rounded = unitIndex === 0 ? n.toFixed(0) : n.toFixed(2);
  return `${rounded} ${units[unitIndex]}`;
}

function pickMetricsBody(env) {
  if (env?.body?.body?.data?.data) return env.body.body.data.data;
  if (env?.body?.data?.data) return env.body.data.data;
  if (env?.body?.data) return env.body.data;
  if (env?.body) return env.body;
  if (env?.data) return env.data;
  return env;
}

let metricsBody = pickMetricsBody(envelope);
if (metricsBody?.data && typeof metricsBody.data === 'object') metricsBody = metricsBody.data;

const jwtPayload = envelope.jwtPayload ?? metricsBody?.jwtPayload ?? null;
const serverName = jwtPayload?.server_name ?? jwtPayload?.server_ip ?? metricsBody?.hostname ?? metricsBody?.server_name ?? metricsBody?.server ?? 'Unknown';
const timestamp = metricsBody?.timestamp ?? jwtPayload?.timestamp ?? null;

const system = metricsBody?.system ?? {};
const memory = system?.memory_mb ?? {};
const totalMem = Number(memory.total);
const usedMem = Number(memory.used);
const memUsedPct = Number.isFinite(totalMem) && totalMem > 0 && Number.isFinite(usedMem) ? (usedMem / totalMem) * 100 : null;

const performance = metricsBody?.performance ?? {};
const databaseStatus = metricsBody?.database_status ?? {};
const locks = metricsBody?.locks ?? {};
const replication = metricsBody?.replication ?? {};
const backup = metricsBody?.backup ?? {};

const storage = metricsBody?.storage ?? {};
const databaseSizeBytes = storage?.database_size?.database_size_bytes ?? null;
const tempTotalBytes = storage?.temp_objects?.temp_objects_total_bytes ?? null;
const tempObjectsCount = storage?.temp_objects?.temp_objects_count ?? null;

const largestTables = Array.isArray(storage?.largest_tables) ? storage.largest_tables : [];
const largestIndexes = Array.isArray(storage?.largest_indexes) ? storage.largest_indexes : [];

const storageSummary = {
  database_size_bytes: databaseSizeBytes,
  database_size_human: storage?.database_size?.database_size ?? bytesToHuman(databaseSizeBytes),
  temp_objects_total_bytes: tempTotalBytes,
  temp_objects_total_human: storage?.temp_objects?.temp_objects_total_size ?? bytesToHuman(tempTotalBytes),
  temp_objects_count: tempObjectsCount,
  largest_tables_top: largestTables.slice(0, 10).map(t => ({
    name: t?.schemaname && t?.table_name ? `${t.schemaname}.${t.table_name}` : (t?.table_name ?? 'Unknown'),
    total_bytes: t?.total_bytes ?? null,
    total_size: t?.total_size ?? bytesToHuman(t?.total_bytes)
  })),
  largest_indexes_top: largestIndexes.slice(0, 10).map(i => ({
    name: i?.schemaname && i?.index_name ? `${i.schemaname}.${i.index_name}` : (i?.index_name ?? 'Unknown'),
    table_name: i?.table_name ?? null,
    index_bytes: i?.index_bytes ?? null,
    index_size: i?.index_size ?? bytesToHuman(i?.index_bytes)
  }))
};

const summary = {
  server: serverName,
  timestamp,
  service_status: databaseStatus?.service_status ?? null,
  connection_status: databaseStatus?.connection_status ?? null,
  disk_usage_percent: system?.disk_usage_percent ?? null,
  load_avg_1min: system?.load_avg?.['1min'] ?? null,
  memory_used_percent: memUsedPct === null ? null : Number(memUsedPct.toFixed(2)),
  total_connections: performance?.total_connections ?? null,
  active_connections: performance?.active_connections ?? null,
  long_running_queries_count: performance?.long_running_queries_count ?? null,
  cache_hit_ratio: performance?.cache_hit_ratio ?? null,
  waiting_sessions: locks?.waiting_sessions ?? null,
  deadlocks: metricsBody?.database?.stats?.deadlocks ?? null,
  connected_replicas: replication?.connected_replicas ?? null,
  archive_mode: backup?.archive_mode ?? null
};

const alerts = [];
if (databaseStatus?.service_status && String(databaseStatus.service_status).toLowerCase() !== 'active') {
  alerts.push({ severity: 'critical', code: 'service_not_active', message: 'Database service is not active', value: databaseStatus.service_status });
}
if (databaseStatus?.connection_status && String(databaseStatus.connection_status).toLowerCase() !== 'success') {
  alerts.push({ severity: 'critical', code: 'connection_failed', message: 'Database connection did not succeed', value: databaseStatus.connection_status });
}
const diskUsage = Number(system?.disk_usage_percent);
if (Number.isFinite(diskUsage) && diskUsage >= 90) {
  alerts.push({ severity: 'critical', code: 'disk_usage_high', message: 'Disk usage is >= 90%', value: diskUsage });
} else if (Number.isFinite(diskUsage) && diskUsage >= 80) {
  alerts.push({ severity: 'warning', code: 'disk_usage_elevated', message: 'Disk usage is >= 80%', value: diskUsage });
}

const normalizedBody = {
  ...metricsBody,
  summary,
  storage_summary: storageSummary,
  alerts
};

const output = {
  ...envelope,
  body: normalizedBody,
  jwtPayload: jwtPayload ?? envelope.jwtPayload
};

return [{ json: output }];

